const APP_SCAN_SW = "/* Service worker Scanner Forte \u2014 apre l'app anche offline e tiene in cache la\n   libreria PDF, cos\u00ec la scansione e la creazione del PDF funzionano senza rete.\n   Tutta la lavorazione delle immagini avviene nel telefono: niente server. */\nvar CACHE = 'scanner-forte-v1';\nvar SHELL = ['/scanner', '/scanner/', '/scanner/manifest.webmanifest',\n             '/scanner/icon-192.png', '/scanner/icon-512.png', '/scanner/jspdf.umd.min.js'];\n\nself.addEventListener('install', function (e) {\n  self.skipWaiting();\n  e.waitUntil(caches.open(CACHE).then(function (c) {\n    return Promise.all(SHELL.map(function (u) { return c.add(new Request(u, { cache: 'reload' })).catch(function () {}); }));\n  }));\n});\nself.addEventListener('activate', function (e) {\n  e.waitUntil(caches.keys().then(function (ks) {\n    return Promise.all(ks.map(function (k) { if (k !== CACHE) return caches.delete(k); }));\n  }).then(function () { return self.clients.claim(); }));\n});\nself.addEventListener('fetch', function (e) {\n  var req = e.request;\n  if (req.method !== 'GET') return;\n  var url = new URL(req.url);\n  if (url.origin !== self.location.origin) return;\n  if (url.pathname.indexOf('/api/') === 0) return;\n  if (req.mode === 'navigate') {\n    e.respondWith(fetch(req).catch(function () { return caches.match('/scanner').then(function (r) { return r || caches.match('/scanner/'); }); }));\n    return;\n  }\n  e.respondWith(caches.match(req).then(function (cached) {\n    var rete = fetch(req).then(function (resp) {\n      if (resp && resp.status === 200) { var copia = resp.clone(); caches.open(CACHE).then(function (c) { c.put(req, copia); }); }\n      return resp;\n    }).catch(function () { return cached; });\n    return cached || rete;\n  }));\n});\n";
const APP_SCAN_MANIFEST = "{\n  \"name\": \"Scanner Forte\",\n  \"short_name\": \"Scanner\",\n  \"description\": \"Scansiona i documenti col telefono: ritaglia da solo, raddrizza, bianco/nero da scanner e crea un PDF. Funziona offline.\",\n  \"start_url\": \"/scanner\",\n  \"scope\": \"/scanner\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#0b0d10\",\n  \"theme_color\": \"#0b2029\",\n  \"lang\": \"it\",\n  \"icons\": [\n    { \"src\": \"/scanner/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/scanner/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/scanner/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\" }\n  ]\n}\n";
const APP_SCAN_ICON192 = Buffer.from("", 'base64');
const APP_SCAN_ICON512 = Buffer.from("", 'base64');
app.get(['/scanner', '/scanner/', '/scanner/index.html'], (req, res) => { res.set('Content-Type', 'text/html; charset=utf-8'); res.send(APP_SCAN_HTML); });
app.get('/scanner/sw.js', (req, res) => { res.set('Content-Type', 'application/javascript; charset=utf-8'); res.set('Service-Worker-Allowed', '/scanner'); res.send(APP_SCAN_SW); });
app.get('/scanner/manifest.webmanifest', (req, res) => { res.set('Content-Type', 'application/manifest+json; charset=utf-8'); res.send(APP_SCAN_MANIFEST); });
app.get('/scanner/icon-192.png', (req, res) => { res.set('Content-Type', 'image/png'); res.set('Cache-Control', 'public, max-age=604800'); res.send(APP_SCAN_ICON192); });
app.get('/scanner/icon-512.png', (req, res) => { res.set('Content-Type', 'image/png'); res.set('Cache-Control', 'public, max-age=604800'); res.send(APP_SCAN_ICON512); });
