/* ==========================================
   ROTTA PUBBLICA: REPORT PROPRIETARIO (SOLO DATI AGGREGATI, NESSUN NOME)
   Pensata per essere condivisa con il proprietario di un immobile: mostra solo conteggi
   (Richieste per Stato ADV FIX, Visioni per Feedback ADV), mai nomi o contatti dei clienti.
   Protetta da una password semplice condivisa (cambiala qui sotto quando vuoi).
========================================== */
const PASSWORD_REPORT_PROPRIETARIO = 'Forte2026'; // non più usata per il controllo, lasciata solo come riferimento storico
// Aggiunge 30 giorni a una data ISO (consegna prevista dell'accesso atti). '' se non valida.
function _dataPiu30ISO(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  d.setDate(d.getDate() + 30);
  return d.toISOString().slice(0, 10);
}

// Etichette della checklist documenti venditore (deve restare allineata a DOC_VENDITORE nel CRM).
const DOC_VENDITORE_ETICHETTE = [
  ['atto-provenienza', 'Atto di provenienza'],
  ['visura-catastale', 'Visura catastale'],
  ['planimetria-catastale', 'Planimetria catastale'],
  ['elaborato-planimetrico', 'Elaborato planimetrico'],
  ['agibilita', 'Agibilità / abitabilità'],
  ['titoli-edilizi', 'Titoli edilizi e pratiche'],
  ['ape', 'APE'],
  ['conformita-impianti', 'Conformità impianti'],
  ['regolamento-condominio', 'Regolamento condominio + millesimi'],
  ['liberatoria-condominio', 'Liberatoria spese condominiali'],
  ['atto-mutuo', 'Atto di mutuo / ipoteca']
];

app.get('/api/report-proprietario/:idElemento', async (req, res) => {
  try {
    const idElemento = req.params.idElemento;
    const incarico = await Incarico.findOne({ idElemento });
    if (!incarico) return res.status(404).json({ error: 'Immobile non trovato' });

    if (!incarico.reportUsername || !incarico.reportPassword) {
      return res.status(403).json({ error: 'Report non ancora attivato per questo immobile' });
    }
    if (req.query.username !== incarico.reportUsername || req.query.password !== incarico.reportPassword) {
      return res.status(401).json({ error: 'Username o password errati' });
    }

    const richieste = await BancaDati.find({ immobileFonteRichiesta: idElemento });
    const visioni = await Visioni.find({ incaricoUfficio: idElemento });

    const contaPerCampo = (elenco, campo) => {
      const conteggio = {};
      elenco.forEach(item => {
        const valore = item[campo] || 'Non specificato';
        conteggio[valore] = (conteggio[valore] || 0) + 1;
      });
      return conteggio;
    };

    const gd = incarico.gestioneDocumenti || {};
    const venditori = gd.venditori || [];

    res.status(200).json({
      indirizzo: incarico.posizione || incarico.nome || '',
      richieste: { totale: richieste.length, perStato: contaPerCampo(richieste, 'statoAdvFix') },
      visioni: { totale: visioni.length, perFeedback: contaPerCampo(visioni, 'feedbackAdv') },
      gestioneProcesso: {
        dataInizio: incarico.dataIncarico || '',
        dataFine: incarico.dataScadenza || '',
        dataPrimoOH: incarico.nextOpenHouse || gd.dataPrimoOH || '',
        fotoFatte: gd.fotoFatte === 'si',
        dataPubblicazionePrevista: gd.dataPubblicazione || '',
        // stato + link veri dei portali (dai campi della riga incarichi); Sito Forte
        // online se pubblicaSito='sempre' o (non 'mai' e stato 'On Line').
        pubblicato: (function () {
          const rif = incarico.idElemento || '';
          const sitoForteOnline = incarico.pubblicaSito === 'sempre'
            || (incarico.pubblicaSito !== 'mai' && incarico.statoImmobile === 'On Line');
          return {
            immobiliareIt: { online: !!(incarico.immobiliareIt || '').trim(), link: (incarico.immobiliareIt || '').trim() },
            idealista:     { online: !!(incarico.idealista || '').trim(),     link: (incarico.idealista || '').trim() },
            wikicasa:      { online: !!(incarico.wikicasa || '').trim(),       link: (incarico.wikicasa || '').trim() },
            sitoForte:     { online: sitoForteOnline, link: 'https://www.immobiliareforte.com/immobili' + (rif ? ('?rif=' + encodeURIComponent(rif)) : '') }
          };
        })(),
        // statistiche portali (visualizzazioni per portale + preferiti) per il report venditore
        viste: (function () {
          const v = incarico.viste || {};
          const n = (x) => parseInt(x, 10) || 0;
          const imm = n(v.immVis), ide = n(v.ideVis), forte = n(v.forteVis);
          return { immobiliare: imm, idealista: ide, sitoForte: forte, totale: imm + ide + forte, preferiti: n(v.immPref), aggiornatoIl: v.aggiornatoIl || '' };
        })(),
        documentiVenditori: { totale: venditori.length, completi: venditori.filter(v => v.cartaIdentita && v.codiceFiscale).length },
        documentiImmobile: {
          provenienzaFatta: !!gd.allegatoProvenienza,
          mutuoGestito: gd.mutuoPresente !== 'si' || !!gd.allegatoAttoMutuo,
          accessoAttiGestito: gd.accessoAttiFatto !== 'si' || !!gd.allegatoUrbanistica
        },
        // checklist documenti venditore: stato (rosso/giallo/comune/verde) per il report del venditore
        documenti: DOC_VENDITORE_ETICHETTE.map(([k, n]) => {
          const v = (gd.documenti || {})[k] || {};
          const out = { chiave: k, nome: n, stato: v.stato || 'rosso', presente: v.stato === 'verde', tipoProvenienza: v.tipoProvenienza || '' };
          if (v.stato === 'comune') {
            out.accesso = {
              stato: v.accessoStato || 'da-presentare',
              dataPresentazione: v.dataPresentazione || '',
              dataPrevista: _dataPiu30ISO(v.dataPresentazione),
              dataRilascio: v.dataRilascio || ''
            };
          }
          return out;
        })
      }
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

